import json, time, urllib.request, urllib.error, datetime, email.utils
BASE='http://localhost:8080'

def request(path, token=None):
    while True:
        headers={}
        if token: [REDACTED_SECRET]'Authorization']='Bearer '+token
        req=urllib.request.Request(BASE+path, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return json.loads(resp.read().decode())
        except urllib.error.HTTPError as e:
            body=e.read().decode(errors='replace')
            if e.code == 401:
                raise RuntimeError('AUTH_EXPIRED')
            if e.code == 429:
                wait=e.headers.get('Retry-After')
                try: delay=float(wait)
                except (TypeError, ValueError):
                    try:
                        dt=email.utils.parsedate_to_datetime(wait)
                        delay=max(0,(dt-datetime.datetime.now(datetime.timezone.utc)).total_seconds())
                    except Exception:
                        try: delay=float(json.loads(body).get('retry_after',1))
                        except Exception: delay=1
                time.sleep(max(0.1,delay)); continue
            # Any transient/request failure is retried rather than abandoning the page.
            time.sleep(1)
        except Exception:
            time.sleep(1)

def token(): return request('/token')['token']

tok=token()
def get(path):
    global tok
    while True:
        try: return request(path,tok)
        except RuntimeError as e:
            if str(e)=='AUTH_EXPIRED': tok=token()
            else: raise

orders={}; duplicates=0
page=1; total_pages=None
while total_pages is None or page<=total_pages:
    data=get('/orders?page='+str(page))
    total_pages=data['total_pages']
    for order in data['items']:
        oid=order['id']
        if oid in orders: duplicates+=1
        else: orders[oid]=order
    page+=1

customers={}
start=datetime.datetime(2025,3,1,tzinfo=datetime.timezone.utc)
end=datetime.datetime(2025,6,1,tzinfo=datetime.timezone.utc)
by={k:0 for k in ('north','south','east','west')}
count=0
for order in orders.values():
    if order['status']"'!='"'shipped': continue
    ts=datetime.datetime.fromisoformat(order['placed_at'].replace('Z','+00:00')).astimezone(datetime.timezone.utc)
    if not (start<=ts<end): continue
    cid=order['customer_id']
    if cid not in customers: customers[cid]=get('/customers/'+str(cid))
    c=customers[cid]
    numerator=order['amount_cents']*(100-c['discount_pct'])
    # Nonnegative currency amounts: integer half-up rounding to cents.
    discounted=(numerator+50)//100
    by[c['region']]+=discounted
    count+=1
result={'total_cents':sum(by.values()),'order_count':count,'duplicates_skipped':duplicates,'by_region':by}
with open('/workspace/result.json','w') as f: json.dump(result,f,indent=2); f.write('\\n')
print(json.dumps(result))
print('unique_orders',len(orders),'customers_cached',len(customers),'pages',total_pages)
